MERGE INTO "DB_FUNCTIONS_ARTICLE_AUTHORS" AS TGT USING (VALUES (CAST(%s AS INTEGER), CAST(%s AS INTEGER))) AS SRC ("ARTICLE_ID", "AUTHOR_ID") ON (TGT."ARTICLE_ID" = SRC."ARTICLE_ID" AND TGT."AUTHOR_ID" = SRC."AUTHOR_ID") WHEN NOT MATCHED THEN INSERT ("ARTICLE_ID", "AUTHOR_ID") VALUES (SRC."ARTICLE_ID", SRC."AUTHOR_ID");
MERGE INTO "DB_FUNCTIONS_ARTICLE_AUTHORS" AS TGT USING (VALUES (CAST(%s AS INTEGER), CAST(%s AS INTEGER))) AS SRC ("ARTICLE_ID", "AUTHOR_ID") ON (TGT."ARTICLE_ID" = SRC."ARTICLE_ID" AND TGT."AUTHOR_ID" = SRC."AUTHOR_ID") WHEN NOT MATCHED THEN INSERT ("ARTICLE_ID", "AUTHOR_ID") VALUES (SRC."ARTICLE_ID", SRC."AUTHOR_ID");
UPDATE "DB_FUNCTIONS_ARTICLE" SET "PUBLISHED" = CURRENT_TIMESTAMP WHERE ("DB_FUNCTIONS_ARTICLE"."ID" = %s AND "DB_FUNCTIONS_ARTICLE"."PUBLISHED" IS NULL);
UPDATE "DB_FUNCTIONS_ARTICLE" SET "TITLE" = %s, "SUMMARY" = NULL, "TEXT" = %s, "WRITTEN" = %s, "PUBLISHED" = (CURRENT_TIMESTAMP + INTEGER((CAST(%s AS BIGINT)) / 86400000000) DAYS + MOD((CAST(%s AS BIGINT)), 86400000000) MICROSECONDS), "UPDATED" = NULL, "VIEWS" = %s WHERE "DB_FUNCTIONS_ARTICLE"."ID" = %s;
UPDATE "DB_FUNCTIONS_AUTHOR" SET "ALIAS" = GREATEST("DB_FUNCTIONS_AUTHOR"."NAME", "DB_FUNCTIONS_AUTHOR"."GOES_BY");
UPDATE "DB_FUNCTIONS_AUTHOR" SET "ALIAS" = LEAST("DB_FUNCTIONS_AUTHOR"."NAME", "DB_FUNCTIONS_AUTHOR"."GOES_BY");
UPDATE "DB_FUNCTIONS_AUTHOR" SET "ALIAS" = LOWER(LEFT("DB_FUNCTIONS_AUTHOR"."NAME", CAST(%s AS INTEGER))) WHERE "DB_FUNCTIONS_AUTHOR"."ALIAS" IS NULL;
UPDATE "DB_FUNCTIONS_AUTHOR" SET "ALIAS" = LOWER(RIGHT("DB_FUNCTIONS_AUTHOR"."NAME", CAST(%s AS INTEGER))) WHERE "DB_FUNCTIONS_AUTHOR"."ALIAS" IS NULL;
UPDATE "DB_FUNCTIONS_AUTHOR" SET "ALIAS" = LOWER(SUBSTRING("DB_FUNCTIONS_AUTHOR"."NAME", CAST(%s AS INTEGER), CAST(%s AS INTEGER))) WHERE "DB_FUNCTIONS_AUTHOR"."ALIAS" IS NULL;
UPDATE "DB_FUNCTIONS_AUTHOR" SET "NAME" = LOWER("DB_FUNCTIONS_AUTHOR"."NAME");
UPDATE "DB_FUNCTIONS_AUTHOR" SET "NAME" = REPLACE("DB_FUNCTIONS_AUTHOR"."NAME", CAST(%s AS NVARCHAR(32)), CAST(%s AS NVARCHAR(32)));
UPDATE "DB_FUNCTIONS_AUTHOR" SET "NAME" = UPPER("DB_FUNCTIONS_AUTHOR"."NAME");
